export interface Note {
  id: string;
  title: string;
  body: string;
  createdAt: string;
}

export interface HandlerOptions {
  now?: () => Date;
}

export function createHandler(
  options?: HandlerOptions,
): (req: Request) => Promise<Response> {
  const store: Note[] = [];
  let nextId = 1;
  const nowFn = options?.now ?? (() => new Date());

  const jsonHeaders = { "Content-Type": "application/json; charset=utf-8" };

  function jsonBody(status: number, data: unknown): Response {
    return new Response(JSON.stringify(data), {
      status,
      headers: jsonHeaders,
    });
  }

  function error(status: number, error: string, extra?: Record<string, unknown>): Response {
    const body = extra ? { error, ...extra } : { error };
    return jsonBody(status, body);
  }

  return async (req: Request): Promise<Response> => {
    const url = new URL(req.url);
    let pathname = url.pathname;

    // Strip one trailing slash
    if (pathname.length > 1 && pathname.endsWith("/")) {
      pathname = pathname.slice(0, -1);
    }

    const parts = pathname.split("/").filter((s) => s.length > 0);
    const method = req.method;

    // Route: /notes
    if (parts.length === 1 && parts[0] === "notes") {
      if (method === "GET") {
        return jsonBody(200, store);
      }
      if (method === "POST") {
        // Parse body
        let parsed: unknown;
        try {
          const text = await req.text();
          if (text.length === 0) throw new Error("empty");
          parsed = JSON.parse(text);
        } catch {
          return error(400, "invalid_json");
        }

        // Validate
        const fields: string[] = [];

        // Treat non-objects as having no keys
        let obj: Record<string, unknown> = {};
        if (
          parsed !== null &&
          typeof parsed === "object" &&
          !Array.isArray(parsed)
        ) {
          obj = parsed as Record<string, unknown>;
        }

        // Check title
        if (
          typeof obj.title !== "string" ||
          obj.title.trim().length < 1 ||
          obj.title.trim().length > 100
        ) {
          fields.push("title");
        }

        // Check body
        if (
          "body" in obj &&
          (typeof obj.body !== "string" || obj.body.length > 10000)
        ) {
          fields.push("body");
        }

        if (fields.length > 0) {
          return error(422, "validation", { fields });
        }

        // Create note
        const id = String(nextId++);
        const note: Note = {
          id,
          title: obj.title.trim(),
          body: "body" in obj ? obj.body as string : "",
          createdAt: nowFn().toISOString(),
        };
        store.push(note);

        return new Response(JSON.stringify(note), {
          status: 201,
          headers: {
            ...jsonHeaders,
            "Location": `/notes/${id}`,
          },
        });
      }
      // Other methods
      return new Response(
        JSON.stringify({ error: "method_not_allowed" }),
        {
          status: 405,
          headers: {
            ...jsonHeaders,
            "Allow": "GET, POST",
          },
        },
      );
    }

